# Database or storage for users and passwords
users = {
    "admin": "password123",
    "user1": "passw0rd"
}

class User(UserMixin):
    def __init__(self, username):
        self.username = username

    @staticmethod
    def get(user_id):
        if user_id == 'admin':
            return User('admin')
        elif user_id == 'user1':
            return User('user1')

@app.route('/')
def home():
    return render_template("home.html")

@login_manager.user_loader
