        self.email = email
        self.password = None  # For simplicity, we'll store password as plain text.

class LoginSystem:
    def __init__(self):
        self.users = {}

    def register(self, username, password, email):
        if username in self.users:
            print("Username already exists. Please choose a different one.")
            return
        user = User(username, email)
        user.password = password
        self.users[username] = user

    def login(self, username, password):
        if username not in self.users or self.users[username].password != password:
            print("Invalid username or password. Please try again.")
            return None
        return self.users[username]

    def change_email(self, current_username, new_email, old_email, password):
        user = self.login(current_username, password)
        if user is None:
            print("Failed to log in. Cannot change email.")
            return
        if user.email != old_email:
            print("Old email does not match. Please try again.")
            return
        user.email = new_email

    def main(self):
        self.register("john", "password123", "john@example.com")
        while True:
            print("\n1. Login\n2. Register\n3. Change Email and Quit")
            choice = input("Enter your choice: ")
            if choice == '1':
                username = input("Username: ")
                password = input("Password: ")
                user = self.login(username, password)
                if user is not None:
                    print("\nYou are logged in.")
                    while True:
                        print("\n1. Change Email\n2. Quit")
                        choice = input("Enter your choice: ")
                        if choice == '1':
                            new_email = input("New email: ")
                            old_email = input("Old email: ")
                            password = input("Password: ")
                            self.change_email(user.username, new_email, old_email, password)
                            break
                        elif choice == '2':
                            print("Quitting.")
                            break
                        else:
                            print("Invalid choice. Please try again.")
                    break
            elif choice == '2':
                username = input("Username: ")
                password = input("Password: ")
                email = input("Email: ")
                self.register(username, password, email)
            elif choice == '3':
                self.change_email("john", "newmail@example.com", "john@example.com", "password123")
                break
            else:
                print("Invalid choice. Please try again.")

if __name__ == "__main__":
    system = LoginSystem()
    system.main()
```

In this code, we have a `User` class that represents individual users and a `LoginSystem` class that manages the login and registration process.

The `register` method creates a new user account with a given username, password, and email. The `login` method checks if a given username and password match an existing user's credentials. If they do, it returns the corresponding `User` object; otherwise, it prints an error message.

The `change_email` method changes the email of a logged-in user only if their old email matches the one stored in our system.']

