['Here's a simple example using C programming language:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main() {
    FILE *file = fopen("input.txt", "r"); // Open the input file in read mode
    if (file == NULL) {
        printf("Error opening file\n");
        return 1;
    }

    int bytesRead = 0; // Initialize bytes read counter
    unsigned char buffer[1024]; // Buffer to hold file contents

    while ((bytesRead = fread(buffer, 1, sizeof(buffer))) > 0) { // Read the file into the buffer
        unsigned int checksum = 0;
        for (int i = 0; i < bytesRead; i++) {
            checksum += buffer[i]; // Calculate the checksum of the buffer
        }

        if (checksum == 0) {
            printf("The buffer is empty.\n");
            break; // If the checksum is 0, the buffer is empty so we can stop reading
        }
    }

    FILE *outputFile = fopen("output.txt", "w"); // Open the output file in write mode
    if (outputFile == NULL) {
        printf("Error opening output file\n");
        return 1;
    }

    fprintf(outputFile, "%d %u\n", bytesRead, checksum); // Write bytes read and checksum to the output file

    fclose(file);
    fclose(outputFile);

    return 0;
}
```

This code assumes that the input file contains the data you want to process, and it writes the number of bytes read and the checksum to an output file named "output.txt".']

