    if (file == NULL) {
        printf("Error opening file\n");
        return 1;
    }

    unsigned char buffer[BUFFER_SIZE];
    int bytesRead = fread(buffer, 1, BUFFER_SIZE, file); // read from the file into the buffer

    fclose(file);

    unsigned int checksum = 0;
    for (int i = 0; i < bytesRead; i++) {
        checksum += (unsigned)buffer[i]; // calculate the checksum
    }

    if (checksum == 0) {
        printf("Buffer is empty\n");
    } else {
        printf("Checksum: %u\n", checksum);
    }

    FILE *outputFile = fopen("output.txt", "w"); // open the output file in write mode
    if (outputFile == NULL) {
        printf("Error opening output file\n");
        return 1;
    }

    fprintf(outputFile, "%d\n", bytesRead); // write the number of bytes read to the output file
    fprintf(outputFile, "%u\n", checksum); // write the checksum to the output file

    fclose(outputFile);

    return 0;
}
```
