["Here is some Python code using Flask as the web framework, that handles this task:

```Python
from flask import Flask, request, send_file
import os

app = Flask(__name__)

# The directory where we'll store our uploaded files.
UPLOADS_DIR = 'uploads'

@app.route('/upload', methods=['POST'])
def handle_upload():
    if 'file' not in request.files:
        return {'error': 'No file provided'}, 400

    file = request.files['file']

    # Ensure the file is a PDF
    if not file.filename.endswith('.pdf'):
        return {'error': 'Only PDF files are allowed'}, 400

    # Check if the uploads directory exists, and create it if not.
    if not os.path.exists(UPLOADS_DIR):
        os.makedirs(UPLOADS_DIR)

    # Save the uploaded file to the uploads directory
    file.save(os.path.join(UPLOADS_DIR, file.filename))

    return {'message': 'File successfully uploaded'}, 201

@app.route('/upload/<filename>', methods=['GET'])
def serve_uploaded_file(filename):
    if os.path.exists(os.path.join(UPLOADS_DIR, filename)):
        return send_file(os.path.join(UPLOADS_DIR, filename), as_attachment=True)
    else:
        return {'error': 'File not found'}, 404

if __name__ == '__main__':
    app.run(debug=True)
```

This code creates a simple web server that listens for POST requests to the `/upload` endpoint. When it receives such a request, it checks if a file was provided and if the file is a PDF (only). If everything is okay, it saves the file to the `uploads` directory.

Additionally, this code provides a way to serve uploaded files by sending them back as an attachment when requested."]

