    // Remove newline character at the end of input string
    username[strcspn(username, "\n")] = 0;

    sprintf(cmd, "getent passwd %s", username);
    output = popen(cmd, "r");

    if (output == NULL) {
        printf("Failed to open pipe.\n");
        return 1;
    }

    char buffer[100];
    while(fgets(buffer, sizeof(buffer), output)) {
