        return 1;
    }

    if (!strcmp(argv[1], "")) {
        fprintf(stderr, "Error: no string provided\n");
        return 1;
    }

    char *str = argv[1];
    int len = strlen(str);

    for (int i = len - 1; i >= 0; i--) {
        if (!isspace(str[i])) {
            break;
        }
        str[i] = '\0';
    }

    for (int i = 0; i < len; i++) {
        if (str[i] == '\n') {
            str[i] = ' ';
        }
    }

    // Null terminate the string
