    if (argc != 2) {
        fprintf(stderr, "Usage: %s <command line argument>\n", argv[0]);
        return 1;
    }

    // Trim trailing whitespace
    int len = strlen(argv[1]);
    for (; len > 0 && isspace(argv[1][len - 1]); len--) {
